-- p11: bloodline rebalance. One bloodline jutsu per rank (Academy..Jonin), unlocked like normal jutsu.
create or replace function public.knows_move(c public.characters, mv public.moves) returns boolean language sql stable set search_path to '' as $$
  select case
    when mv.scroll then c.scrolls ? mv.id
    when mv.style = 'none' then true
    when mv.style = 'bloodline' then mv.bloodline = c.bloodline and mv.tier <= public.rank_index(c.rank)
    when mv.tier > public.rank_index(c.rank) then false
    when mv.style = 'ninjutsu' then mv.element in (c.element, coalesce(c.element2, ''))
    else true end $$;
